<?php
if(!defined('ALLOWED_ACCESS'))exit('Forbidden');
require_once __DIR__.'/armory_traits.php';
$talentData=armory_character_traits($world_db,$char_db,(int)$character['guid'],(int)$character['class']);
$traitEsc=static fn($s)=>htmlspecialchars((string)$s,ENT_QUOTES,'UTF-8');
$traitIcon=static fn($s)=>preg_match('/^[a-z0-9_\-]+$/i',(string)$s)?(string)$s:'inv_misc_questionmark';
?>
<style>.trait-loadouts{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:20px}.trait-loadouts button{padding:10px 16px;background:#101b2b;border:1px solid #40516a;color:#b9c8de;cursor:pointer;font-size:12px}.trait-loadouts button.active{color:#ebce8c;border-color:#c3a665;background:#242119}.trait-build[hidden]{display:none}.trait-tree-wrap{overflow-x:auto;background:#080d16;border:1px solid #344155;padding:22px;margin:16px 0}.trait-tree{display:grid;grid-template-columns:repeat(var(--columns),minmax(65px,1fr));gap:22px 10px;min-width:calc(var(--columns)*72px);max-width:100%;margin-top:20px}.trait-node{position:relative;display:flex;justify-content:center}.trait-node img{width:48px;height:48px;object-fit:cover;border:2px solid #455063;box-shadow:0 2px 7px #000}.trait-node.learned img{border-color:#dfbf70;box-shadow:0 0 12px #dcb96740}.trait-node.unlearned img{filter:grayscale(.85);opacity:.6}.trait-node .trait-rank{position:absolute;bottom:-5px;left:50%;transform:translateX(-50%);font:11px Arial;background:#060a12;color:#cbb77f;padding:2px 5px;border:1px solid #6f6240}.trait-node .trait-tip{display:none;position:absolute;bottom:62px;left:50%;transform:translateX(-50%);z-index:25;background:#080e1af7;border:1px solid #bc9f60;color:#d4deed;padding:12px;width:230px;font:12px/1.6 Arial;text-align:left;box-shadow:0 10px 25px #000a}.trait-node:hover .trait-tip,.trait-node:focus-within .trait-tip{display:block}.trait-tip strong{color:#ffd100;display:block;font-size:14px}.trait-book{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:12px}.trait-spell{display:flex;gap:12px;padding:12px;background:#0b1320;border:1px solid #304159;align-items:center}.trait-spell img{width:40px;height:40px;border:1px solid #8b7849}.trait-spell strong{font-size:13px;color:#d5c091}.trait-spell small{display:block;font-size:11px;color:#8198b8}.trait-note{color:#8da0ba;font-size:12px;line-height:1.7;margin:12px 0}.trait-title{font:600 18px Cinzel,Georgia,serif;color:#e5ca8a}.trait-rank-count{font-size:12px;color:#93a5be}</style>
<?php if(!$talentData['ready']):?><p class="trait-note"><?php echo translate('armory_library_pending','The server talent library is not available yet. Start the updated worldserver once.'); ?></p>
<?php elseif(!$talentData['configs']):?><p class="trait-note"><?php echo translate('armory_no_talent_build','No saved talent configuration is available for this character.'); ?></p>
<?php else:?>
<p class="trait-note"><?php echo translate('armory_traits_note','These trees come from this server’s actual client data. Ranks reflect saved character configurations; grey icons are unlearned talents. Online changes appear after the character is saved.'); ?></p>
<div class="trait-loadouts"><?php foreach($talentData['configs'] as $index=>$build):?><button type="button" data-trait-build="<?php echo $index; ?>" class="<?php echo $index===0?'active':''; ?>"><?php echo $traitEsc($build['name']); ?> · <?php echo (int)$build['points']; ?> <?php echo translate('armory_points_spent','points spent'); ?><?php echo $build['active']?' · '.translate('armory_active','Active'):''; ?></button><?php endforeach;?></div>
<?php foreach($talentData['configs'] as $index=>$build):?><div class="trait-build" id="trait-build-<?php echo $index; ?>" <?php echo $index===0?'':'hidden'; ?>><?php $trees=[];foreach($build['nodes'] as $node)$trees[(int)$node['TraitTreeID']][]=$node;foreach($trees as $treeId=>$nodes){$xs=array_values(array_unique(array_map(static fn($n)=>(int)$n['PosX'],$nodes)));$ys=array_values(array_unique(array_map(static fn($n)=>(int)$n['PosY'],$nodes)));sort($xs);sort($ys);$columns=count($xs);?>
<div class="trait-tree-wrap"><h3 class="trait-title"><?php echo $traitEsc($nodes[0]['TitleText']?:$build['name']); ?></h3><div class="trait-tree" style="--columns:<?php echo max(1,$columns); ?>">
<?php foreach($nodes as $node){$rank=(int)$node['rank'];$max=(int)$node['MaxRanks'];$spell=(int)$node['SpellID'];if(!$spell)continue;$col=array_search((int)$node['PosX'],$xs,true)+1;$row=array_search((int)$node['PosY'],$ys,true)+1;?><div class="trait-node <?php echo $rank>0?'learned':'unlearned'; ?>" style="grid-column:<?php echo $col; ?>;grid-row:<?php echo $row; ?>"><a <?php echo $spell<200000?'href="https://www.wowhead.com/classic/spell='.$spell.'" target="_blank" rel="noopener"':'tabindex="0"'; ?> aria-label="<?php echo $traitEsc($node['name'].' '.$rank.'/'.$max); ?>"><img src="https://wow.zamimg.com/images/wow/icons/large/<?php echo $traitIcon($node['icon']); ?>.jpg" alt="<?php echo $traitEsc($node['name']); ?>" loading="lazy"><span class="trait-rank"><?php echo $rank.'/'.$max; ?></span><span class="trait-tip"><strong><?php echo $traitEsc($node['name']); ?></strong><?php echo translate('armory_rank','Rank').' '.$rank.'/'.$max; ?><br>Spell #<?php echo $spell; ?><?php if($node['OverrideDescription']&&!preg_match('/\$[a-z0-9]/i',$node['OverrideDescription'])): ?><br><?php echo $traitEsc($node['OverrideDescription']); ?><?php endif;?></span></a></div><?php }?></div></div><?php }?></div><?php endforeach;?>
<script>document.querySelectorAll('[data-trait-build]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.trait-build').forEach(panel=>panel.hidden=panel.id!=='trait-build-'+button.dataset.traitBuild);document.querySelectorAll('[data-trait-build]').forEach(other=>other.classList.toggle('active',other===button));}));</script>
<?php endif;?>
<h3 class="trait-title" style="margin:25px 0 14px"><?php echo translate('armory_spellbook','Spellbook'); ?></h3><div class="trait-book"><?php foreach($talentData['spells'] as $spell):?><div class="trait-spell"><img src="https://wow.zamimg.com/images/wow/icons/large/<?php echo $traitIcon($spell['icon']); ?>.jpg" alt="" loading="lazy"><div><strong><?php echo $traitEsc($spell['Name']); ?></strong><small>Spell #<?php echo (int)$spell['ID']; ?></small></div></div><?php endforeach;?></div>
<?php if(!$talentData['spells']&&$talentData['ready']):?><p class="trait-note"><?php echo translate('armory_no_spells','No active learned spells have been saved for this character.'); ?></p><?php endif;?>
<h3 class="trait-title" style="margin:25px 0 14px"><?php echo translate('armory_skills','Skills & professions'); ?></h3><div class="trait-book"><?php foreach($talentData['skills'] as $skill):?><div class="trait-spell"><img src="https://wow.zamimg.com/images/wow/icons/large/<?php echo $traitIcon($skill['icon']); ?>.jpg" alt="" loading="lazy"><div><strong><?php echo $traitEsc($skill['name']); ?></strong><small><?php echo (int)$skill['value'].' / '.(int)$skill['max']; ?></small></div></div><?php endforeach;?></div>
